package local.tvmorph.tv;
import android.app.*;import android.content.*;import java.net.*;import java.io.*;import java.util.concurrent.*;import org.json.*;
/** A timer may only be configured with a server-verified Plus entitlement. Existing PINs and limits remain enforced offline. */
final class PlusAccess {
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();private static String verifiedToken="";private static long verifiedAt;
 static synchronized void invalidate(){verifiedToken="";verifiedAt=0;}
 static synchronized boolean verified(Context context){boolean allowed=false;try{String token=new JSONObject(PlusIdentity.read(context)).optString("token");if(!token.isEmpty()&&token.equals(verifiedToken)&&System.currentTimeMillis()-verifiedAt<300000)allowed=true;else if(!token.isEmpty()){HttpURLConnection connection=(HttpURLConnection)new URL("https://morph-tv.com/api/plus/status").openConnection();try{connection.setConnectTimeout(8000);connection.setReadTimeout(8000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] data=new JSONObject().put("token",token).toString().getBytes("UTF-8");connection.setFixedLengthStreamingMode(data.length);try(OutputStream out=connection.getOutputStream()){out.write(data);}if(connection.getResponseCode()==200){ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=connection.getInputStream()){byte[] buffer=new byte[1024];int n;while((n=input.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>16384)throw new IOException("Response too large");}}JSONObject response=new JSONObject(bytes.toString("UTF-8"));allowed=response.optBoolean("active")&&response.optString("scope").equals(context.getPackageName().equals("local.cleartv.mobile")?"studio":"tv");if(allowed){verifiedToken=token;verifiedAt=System.currentTimeMillis();}}}finally{connection.disconnect();}}}catch(Exception ignored){}return allowed;}
 static void require(Activity activity,Runnable done){worker.execute(()->{final boolean allowed=verified(activity);final boolean ok=allowed;activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;if(ok)done.run();else new AlertDialog.Builder(activity).setTitle("Morph Plus").setMessage(FamilyText.t(activity,"قفل التطبيقات بالوقت ضمن Plus. فعّل Plus من الإعدادات، وتأكد من الإنترنت للتحقق من التفعيل.","Timed app locks are included in Plus. Activate Plus in Settings and connect to the internet to verify activation.")).setPositiveButton(FamilyText.t(activity,"رجوع","Back"),null).show();});});}
}
